#!/usr/bin/env bash
#
# install-edr-agent-linux.sh  --  MamorAI agent pack (Linux)  (EDR-130)
#
#   Installs or updates on one server: [Tailscale] -> Wazuh agent -> auditd rules -> [docker-listener]
#   -> [MamorAI SSH access], and checks the connection to the Wazuh manager.
#   Settings come from config.json next to this script, generated by MamorAI (host screen -> "Agent pack").
#   Safe to run again.
#
#   Supported: Debian / Ubuntu (apt), RHEL / CentOS / Rocky / Alma / Fedora / Amazon Linux (dnf | yum)
#
#   Usage:
#     sudo ./install-edr-agent-linux.sh                     asks: install / update
#     sudo ./install-edr-agent-linux.sh --mode update --yes no questions (cron, Ansible, a loop over SSH, ...)
#     sudo ./install-edr-agent-linux.sh --mode install --password '<enrollment password>' --yes
#     sudo ./install-edr-agent-linux.sh --dry-run           checks only, changes nothing
#
#   Options:
#     --mode auto|install|update   auto (default): install when no agent, otherwise ask (update with --yes)
#     --password <pw>              Wazuh enrollment password (default: config.json, else asked)
#     --authkey <tskey-...>        Tailscale auth key (when the pack uses Tailscale)
#     --manager <a,b>              manager addresses in order (default: config.json)
#     --group <name>               Wazuh agent group (default: config.json)
#     --name <name>                agent name (default: hostname -s)
#     --no-tailscale / --no-auditd / --docker / --no-docker
#     --mamorai-ssh / --no-mamorai-ssh   let MamorAI operate this server over SSH (default: asked, answer "no")
#     --keep-files                 keep the extracted pack (default: deleted after a successful run, it holds secrets)
#     --yes                        no questions
#     --dry-run                    checks only
#
#   Exit code: 0 = done, 1 = failed, 2 = cancelled.   Log: /var/log/mamorai-agent-install.log
#
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LOG="/var/log/mamorai-agent-install.log"
STATE_DIR="/etc/mamorai"
STATE="$STATE_DIR/pack.json"
OSSEC="/var/ossec/etc/ossec.conf"

MODE=auto; REG_PASS=""; TS_AUTHKEY=""; MANAGERS=""; AGENT_GROUP=""; AGENT_NAME="$(hostname -s 2>/dev/null || hostname)"
DO_TAILSCALE=""; DO_AUDITD=""; DO_DOCKER=""; DO_SSH=ask; YES=0; DRY_RUN=0; KEEP_FILES=0

c_reset=$'\033[0m'; c_ok=$'\033[32m'; c_warn=$'\033[33m'; c_err=$'\033[31m'; c_inf=$'\033[36m'; c_step=$'\033[35m'
log() {
  local lvl="${2:-INFO}" col="$c_inf"
  case "$lvl" in OK) col="$c_ok";; WARN) col="$c_warn";; FAIL) col="$c_err";; STEP) col="$c_step";; esac
  printf '%s [%s] %s%s%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$lvl" "$col" "$1" "$c_reset"
  printf '%s [%s] %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$lvl" "$1" >> "$LOG" 2>/dev/null || true
}
die() { log "$1" FAIL; log "stopped. log: $LOG" FAIL; exit 1; }
ask() { # ask "question" default(y|n) -> 0 = yes
  local a; [ "$YES" -eq 1 ] && { [ "$2" = y ]; return; }
  [ -t 0 ] || { [ "$2" = y ]; return; }
  read -r -p "  $1 [$( [ "$2" = y ] && echo Y/n || echo y/N )] " a
  a="${a:-$2}"; case "$a" in y|Y|yes|YES) return 0;; *) return 1;; esac
}

while [ $# -gt 0 ]; do
  case "$1" in
    --mode)      MODE="${2:-}"; shift 2;;
    --password)  REG_PASS="${2:-}"; shift 2;;
    --authkey)   TS_AUTHKEY="${2:-}"; shift 2;;
    --manager)   MANAGERS="${2:-}"; shift 2;;
    --group)     AGENT_GROUP="${2:-}"; shift 2;;
    --name)      AGENT_NAME="${2:-}"; shift 2;;
    --no-tailscale) DO_TAILSCALE=0; shift;;
    --no-auditd)    DO_AUDITD=0; shift;;
    --docker)       DO_DOCKER=yes; shift;;
    --no-docker)    DO_DOCKER=no; shift;;
    --mamorai-ssh)    DO_SSH=yes; shift;;
    --no-mamorai-ssh) DO_SSH=no; shift;;
    --yes|-y)    YES=1; shift;;
    --keep-files) KEEP_FILES=1; shift;;
    --dry-run)   DRY_RUN=1; shift;;
    -h|--help)   sed -n '2,32p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; exit 0;;
    *) die "unknown option: $1 (see --help)";;
  esac
done
case "$MODE" in auto|install|update) ;; *) die "--mode must be auto, install or update";; esac

[ "$(id -u)" -eq 0 ] || die "run as root: sudo $0 ..."
mkdir -p "$(dirname "$LOG")"; : >> "$LOG"; chmod 600 "$LOG" 2>/dev/null || true
echo
log "===== MamorAI agent pack (Linux) =====" STEP

# ---------- pack + config ----------
CFG="$HERE/config.json"; PACKJ="$HERE/pack.json"
[ -f "$CFG" ] || die "config.json not found next to this script"
command -v python3 >/dev/null 2>&1 && PY=python3 || PY=""
cfg() { # cfg <python expression on c>   (falls back to a simple sed for plain string keys)
  if [ -n "$PY" ]; then "$PY" -c "import json,sys; c=json.load(open(sys.argv[1])); v=$1; print('' if v is None else (','.join(map(str,v)) if isinstance(v,list) else (str(v).lower() if isinstance(v,bool) else v)))" "$CFG" 2>/dev/null
  else local k; k="$(echo "$1" | sed -n "s/^c\.get('\([A-Za-z]*\)'.*/\1/p")"; sed -n "s/.*\"$k\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" "$CFG" | head -1; fi
}
PACK_REV="$( [ -f "$PACKJ" ] && sed -n 's/.*"rev"[[:space:]]*:[[:space:]]*\([0-9]*\).*/\1/p' "$PACKJ" | head -1 )"; PACK_REV="${PACK_REV:-0}"
WAZUH_VERSION="$(cfg "c.get('wazuhVersion','')")"
[ -n "$MANAGERS" ]    || MANAGERS="$(cfg "c.get('managerAddresses',[])")"
[ -n "$AGENT_GROUP" ] || AGENT_GROUP="$(cfg "c.get('group','default')")"
[ -n "$REG_PASS" ]    || REG_PASS="$(cfg "c.get('registrationPassword','')")"
[ -n "$TS_AUTHKEY" ]  || TS_AUTHKEY="$(cfg "c.get('tailscaleAuthKey','')")"
[ -n "$DO_TAILSCALE" ] || { [ "$(cfg "c.get('useTailscale',False)")" = true ] && DO_TAILSCALE=1 || DO_TAILSCALE=0; }
[ -n "$DO_AUDITD" ]    || { [ "$(cfg "c.get('auditd',True)")" = false ] && DO_AUDITD=0 || DO_AUDITD=1; }
[ -n "$DO_DOCKER" ]    || DO_DOCKER="$(cfg "c.get('docker','auto')")"; DO_DOCKER="${DO_DOCKER:-auto}"
SSH_OFFER="$(cfg "(c.get('mamoraiSsh') or {}).get('offer',False)")"
SSH_USER="$(cfg "(c.get('mamoraiSsh') or {}).get('user','mamorai')")"; SSH_USER="${SSH_USER:-mamorai}"
SSH_PUB="$(cfg "(c.get('mamoraiSsh') or {}).get('publicKey','')")"
SSH_FROM="$(cfg "(c.get('mamoraiSsh') or {}).get('allowFrom',[])")"
SSH_SUDO="$(cfg "(c.get('mamoraiSsh') or {}).get('sudo','full')")"
[ -n "$WAZUH_VERSION" ] || die "config.json: wazuhVersion is empty"
[ -n "$MANAGERS" ] || die "config.json: no manager address (managerAddresses)"
FIRST_MANAGER="${MANAGERS%%,*}"
[[ "$AGENT_GROUP" =~ ^[A-Za-z0-9_.,-]+$ ]] || die "invalid group: $AGENT_GROUP"
[[ "$WAZUH_VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+-[0-9]+$ ]] || die "invalid wazuhVersion: $WAZUH_VERSION"
[[ "$SSH_USER" =~ ^[a-z_][a-z0-9_-]{0,31}$ ]] || die "invalid mamoraiSsh.user"

# integrity (SHA256SUMS.txt written by MamorAI)
if [ -f "$HERE/SHA256SUMS.txt" ] && command -v sha256sum >/dev/null 2>&1; then
  ( cd "$HERE" && sha256sum --quiet -c SHA256SUMS.txt ) >>"$LOG" 2>&1 || die "pack files were changed after MamorAI built them (sha256sum -c SHA256SUMS.txt)"
  log "pack r$PACK_REV: all files match SHA256SUMS.txt" OK
else log "SHA256SUMS.txt or sha256sum missing: integrity of the pack is not checked" WARN; fi

# ---------- OS ----------
. /etc/os-release 2>/dev/null || die "cannot read /etc/os-release"
OS_ID="${ID:-unknown}"
case "$OS_ID" in
  debian|ubuntu|raspbian) PKG=apt ;;
  rhel|centos|rocky|almalinux|fedora|amzn|ol) PKG=$(command -v dnf >/dev/null 2>&1 && echo dnf || echo yum) ;;
  *) case "${ID_LIKE:-}" in *debian*) PKG=apt;; *rhel*|*fedora*) PKG=$(command -v dnf >/dev/null 2>&1 && echo dnf || echo yum);; *) die "unsupported distribution: $OS_ID";; esac ;;
esac
log "OS: ${PRETTY_NAME:-$OS_ID} / $(uname -m) / $PKG" OK

# ---------- what is installed ----------
HAVE_AGENT=0; HAVE_VER=""
if [ -x /var/ossec/bin/wazuh-control ]; then
  HAVE_AGENT=1
  HAVE_VER="$(/var/ossec/bin/wazuh-control info -v 2>/dev/null | tr -d 'v' | head -1)"
  [ -n "$HAVE_VER" ] || HAVE_VER="$(sed -n 's/^WAZUH_VERSION="v\{0,1\}\([^"]*\)".*/\1/p' /etc/ossec-init.conf 2>/dev/null)"
fi
HAVE_REV="$( [ -f "$STATE" ] && sed -n 's/.*"rev"[[:space:]]*:[[:space:]]*\([0-9]*\).*/\1/p' "$STATE" | head -1 )"
echo
echo "  This pack  : r$PACK_REV  (Wazuh agent $WAZUH_VERSION, manager $MANAGERS, group $AGENT_GROUP)"
echo "  This server: agent ${HAVE_VER:-not installed} / pack ${HAVE_REV:+r}${HAVE_REV:--}"
echo

if [ "$MODE" = auto ]; then
  if [ "$HAVE_AGENT" -eq 0 ]; then ask "The Wazuh agent is not installed. Install now?" y || { log cancelled WARN; exit 2; }; MODE=install
  else ask "The Wazuh agent is installed. Update it with this pack (settings, auditd, agent version)?" y || { log cancelled WARN; exit 2; }; MODE=update; fi
fi
[ "$MODE" = update ] && [ "$HAVE_AGENT" -eq 0 ] && die "the Wazuh agent is not installed: use --mode install"
[ "$MODE" = install ] && [ "$HAVE_AGENT" -eq 1 ] && { log "the Wazuh agent is already installed: continuing as an update (enrollment is kept)" WARN; MODE=update; }
log "mode: $MODE" STEP

if [ "$MODE" = install ] && [ -z "$REG_PASS" ] && [ "$DRY_RUN" -eq 0 ]; then
  if [ "$YES" -eq 1 ] || [ ! -t 0 ]; then die "enrollment password missing: --password or a pack downloaded with the password"; fi
  read -r -s -p "  Wazuh enrollment password (ask your administrator): " REG_PASS; echo
  [ -n "$REG_PASS" ] || die "enrollment password is required"
fi

# MamorAI SSH access (asked; default no)
if [ "$DO_SSH" = ask ]; then
  if [ "$SSH_OFFER" = true ] && [ -n "$SSH_PUB" ]; then
    if id "$SSH_USER" >/dev/null 2>&1 && grep -qs 'mamorai-agent-pack' "$(getent passwd "$SSH_USER" | cut -d: -f6)/.ssh/authorized_keys"; then DO_SSH=yes
    elif ask "Let MamorAI scan and operate this server over SSH (user '$SSH_USER', from ${SSH_FROM:-anywhere}, sudo: $SSH_SUDO)?" n; then DO_SSH=yes; else DO_SSH=no; fi
  else DO_SSH=no; fi
fi
[ "$DO_SSH" = yes ] && { [ -n "$SSH_PUB" ] || die "this pack has no MamorAI SSH key (enable it in MamorAI: settings -> agent pack)"; }

# ---------- checks ----------
probe() { timeout 4 bash -c "echo > /dev/tcp/$1/1514" 2>/dev/null; }
REACH=""
for m in ${MANAGERS//,/ }; do probe "$m" && { REACH="$m"; break; }; done
[ -n "$REACH" ] && log "manager reachable: $REACH:1514" OK || log "manager not reachable yet ($MANAGERS) — normal before Tailscale is up"
DISK=$(df -Pm / | awk 'NR==2{print $4}'); [ "${DISK:-0}" -lt 500 ] && log "less than 500 MB free on /" WARN
if [ "$DRY_RUN" -eq 1 ]; then log "--dry-run: nothing changed" OK; exit 0; fi

pkg_install() { if [ "$PKG" = apt ]; then DEBIAN_FRONTEND=noninteractive apt-get install -y "$@" >>"$LOG" 2>&1; else "$PKG" install -y "$@" >>"$LOG" 2>&1; fi; }
pkg_refresh() { if [ "$PKG" = apt ]; then apt-get update >>"$LOG" 2>&1; else "$PKG" makecache -y >>"$LOG" 2>&1 || true; fi; }

pkg_refresh || log "package index update reported warnings (continuing)" WARN
pkg_install curl ca-certificates gnupg >/dev/null 2>&1 || true

# ---------- 1. Tailscale ----------
if [ "$DO_TAILSCALE" -eq 1 ]; then
  log "--- Tailscale ---" STEP
  if ! command -v tailscale >/dev/null 2>&1; then
    curl -fsSL https://tailscale.com/install.sh | sh >>"$LOG" 2>&1 || die "Tailscale install failed (see $LOG)"
    log "Tailscale installed" OK
  fi
  systemctl enable --now tailscaled >>"$LOG" 2>&1 || true
  if tailscale status >/dev/null 2>&1; then log "already in the tailnet: $(tailscale ip -4 2>/dev/null | head -1)" OK
  else
    [ -n "$TS_AUTHKEY" ] || die "Tailscale is not logged in: give --authkey tskey-... (or --no-tailscale)"
    tailscale up --authkey "$TS_AUTHKEY" --ssh=false --accept-dns=false >>"$LOG" 2>&1 || die "tailscale up failed (is the auth key still valid?)"
    log "joined the tailnet: $(tailscale ip -4 2>/dev/null | head -1)" OK
  fi
  for _ in $(seq 1 10); do for m in ${MANAGERS//,/ }; do probe "$m" && { REACH="$m"; break 2; }; done; sleep 2; done
fi
if [ -z "$REACH" ]; then
  [ "$MODE" = install ] && die "cannot reach the manager ($MANAGERS) on 1514/tcp"
  log "manager not reachable right now: settings are applied anyway" WARN
fi
ENROLL="${REACH:-$FIRST_MANAGER}"

# ---------- 2. Wazuh agent ----------
log "--- Wazuh agent ---" STEP
repo_setup() {
  if [ "$PKG" = apt ]; then
    install -d -m 0755 /usr/share/keyrings
    [ -s /usr/share/keyrings/wazuh.gpg ] || curl -fsSL https://packages.wazuh.com/key/GPG-KEY-WAZUH | gpg --no-default-keyring --keyring gnupg-ring:/usr/share/keyrings/wazuh.gpg --import >>"$LOG" 2>&1 || die "cannot import the Wazuh GPG key"
    chmod 644 /usr/share/keyrings/wazuh.gpg
    echo "deb [signed-by=/usr/share/keyrings/wazuh.gpg] https://packages.wazuh.com/4.x/apt/ stable main" > /etc/apt/sources.list.d/wazuh.list
    apt-get update >>"$LOG" 2>&1 || die "Wazuh repository update failed"
  else
    rpm --import https://packages.wazuh.com/key/GPG-KEY-WAZUH >>"$LOG" 2>&1 || die "cannot import the Wazuh GPG key"
    printf '[wazuh]\ngpgcheck=1\ngpgkey=https://packages.wazuh.com/key/GPG-KEY-WAZUH\nenabled=1\nname=Wazuh repository\nbaseurl=https://packages.wazuh.com/4.x/yum/\nprotect=1\n' > /etc/yum.repos.d/wazuh.repo
  fi
}
install_agent_version() { # the exact version of the pack (packages are GPG-checked by apt / dnf)
  if [ "$PKG" = apt ]; then
    apt-mark unhold wazuh-agent >>"$LOG" 2>&1 || true
    DEBIAN_FRONTEND=noninteractive apt-get install -y "wazuh-agent=$WAZUH_VERSION" >>"$LOG" 2>&1
    local rc=$?; apt-mark hold wazuh-agent >>"$LOG" 2>&1 || true; return $rc
  else
    sed -i '/^exclude=wazuh-agent$/d' /etc/yum.conf 2>/dev/null || true
    "$PKG" install -y "wazuh-agent-$WAZUH_VERSION" >>"$LOG" 2>&1; local rc=$?
    grep -q '^exclude=wazuh-agent$' /etc/yum.conf 2>/dev/null || echo 'exclude=wazuh-agent' >> /etc/yum.conf
    return $rc
  fi
}
verlt() { [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | head -1)" = "$1" ]; }
PACK_V="${WAZUH_VERSION%-*}"
if [ "$MODE" = install ]; then
  repo_setup
  export WAZUH_MANAGER="$MANAGERS" WAZUH_REGISTRATION_SERVER="$ENROLL" WAZUH_REGISTRATION_PASSWORD="$REG_PASS" WAZUH_AGENT_GROUP="$AGENT_GROUP" WAZUH_AGENT_NAME="$AGENT_NAME"
  install_agent_version || die "Wazuh agent install failed (see $LOG)"
  unset WAZUH_REGISTRATION_PASSWORD; REG_PASS=""
  log "Wazuh agent $WAZUH_VERSION installed (name $AGENT_NAME, group $AGENT_GROUP)" OK
elif [ -n "$HAVE_VER" ] && verlt "$HAVE_VER" "$PACK_V"; then
  repo_setup
  log "upgrading the Wazuh agent $HAVE_VER -> $PACK_V (enrollment is kept)"
  install_agent_version || die "Wazuh agent upgrade failed (see $LOG)"
  log "Wazuh agent upgraded" OK
elif [ -n "$HAVE_VER" ] && verlt "$PACK_V" "$HAVE_VER"; then log "agent $HAVE_VER is newer than this pack ($PACK_V): kept" WARN
else log "Wazuh agent ${HAVE_VER:-?}: no change needed" OK; fi

# manager list in ossec.conf (order of this pack)
if [ -f "$OSSEC" ]; then
  CUR="$(grep -oP '(?<=<address>)[^<]+' "$OSSEC" 2>/dev/null | paste -sd, -)"
  if [ "$CUR" != "$MANAGERS" ]; then
    if [ -n "$PY" ]; then
      cp -p "$OSSEC" "$OSSEC.bak-$(date +%Y%m%d-%H%M%S)"
      "$PY" - "$OSSEC" "$MANAGERS" <<'PYEOF' || die "could not update ossec.conf"
import re, sys
p, mgrs = sys.argv[1], [m for m in sys.argv[2].split(",") if m]
s = open(p).read()
m = re.search(r"<client>.*?</client>", s, re.S)
if not m: sys.exit(1)
blk = m.group(0)
proto = re.search(r"<protocol>([^<]+)</protocol>", blk); proto = proto.group(1) if proto else "tcp"
blk2 = re.sub(r"\s*<server>.*?</server>", "", blk, flags=re.S)
servers = "".join(f"\n    <server>\n      <address>{a}</address>\n      <port>1514</port>\n      <protocol>{proto}</protocol>\n    </server>" for a in mgrs)
blk2 = blk2.replace("<client>", "<client>" + servers, 1)
open(p, "w").write(s[:m.start()] + blk2 + s[m.end():])
PYEOF
      log "ossec.conf <server>: $MANAGERS" OK
    else
      sed -i "0,/<address>.*<\/address>/s//<address>$FIRST_MANAGER<\/address>/" "$OSSEC"; log "ossec.conf manager set to $FIRST_MANAGER (python3 missing: only the first address)" WARN
    fi
  else log "ossec.conf <server>: already correct" OK; fi
fi

# ---------- 3. auditd ----------
if [ "$DO_AUDITD" -eq 1 ]; then
  log "--- auditd (process execution, like Sysmon on Windows) ---" STEP
  if [ "$PKG" = apt ]; then pkg_install auditd audispd-plugins || pkg_install auditd || log "auditd install reported warnings" WARN
  else pkg_install audit || log "audit install reported warnings" WARN; fi
  install -d -m 0750 /etc/audit/rules.d
  cat > /etc/audit/rules.d/mamorai-wazuh.rules <<'AUDITEOF'
## MamorAI agent pack: process execution for Wazuh (auditd decoder) and the MamorAI process tree.
## Only commands of logged-in users (auid >= 1000, also across sudo); daemons are left out on purpose:
## without this filter Wazuh's own SCA / rootcheck commands produce >100k alerts a day per server.
## What daemons run is covered by FIM (/etc, /usr/bin, /usr/sbin), SCA and rootcheck.
-a exit,always -F arch=b64 -S execve -F auid>=1000 -F auid!=4294967295 -k audit-wazuh-c
-a exit,always -F arch=b32 -S execve -F auid>=1000 -F auid!=4294967295 -k audit-wazuh-c
## changes to privilege escalation settings, whoever makes them
-w /etc/sudoers -p wa -k audit-wazuh-sudoers
-w /etc/sudoers.d/ -p wa -k audit-wazuh-sudoers
AUDITEOF
  [ -f /etc/audit/rules.d/wazuh.rules ] && grep -q 'audit-wazuh-c' /etc/audit/rules.d/wazuh.rules && mv /etc/audit/rules.d/wazuh.rules /etc/audit/rules.d/wazuh.rules.replaced-by-mamorai
  augenrules --load >>"$LOG" 2>&1 || log "augenrules --load reported warnings" WARN
  systemctl enable --now auditd >>"$LOG" 2>&1 || service auditd restart >>"$LOG" 2>&1 || log "auditd did not start" WARN
  # (if the agent group's shared agent.conf reads it too, logcollector skips the duplicate)
  if [ -f "$OSSEC" ] && ! grep -q '/var/log/audit/audit.log' "$OSSEC"; then
    sed -i 's|</ossec_config>|  <localfile>\n    <log_format>audit</log_format>\n    <location>/var/log/audit/audit.log</location>\n  </localfile>\n\n</ossec_config>|' "$OSSEC"
  fi
  log "auditd configured" OK
fi

# ---------- 4. docker-listener ----------
EN_DOCKER=0
case "$DO_DOCKER" in yes) EN_DOCKER=1;; no) EN_DOCKER=0;; *) command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1 && EN_DOCKER=1;; esac
if [ "$EN_DOCKER" -eq 1 ]; then
  log "--- docker-listener ---" STEP
  pkg_install python3-pip >/dev/null 2>&1 || true
  python3 -c 'import docker' 2>/dev/null || python3 -m pip install --quiet 'docker==6.0.0' >>"$LOG" 2>&1 || python3 -m pip install --quiet --break-system-packages 'docker==6.0.0' >>"$LOG" 2>&1 || log "python docker library missing: docker-listener will not work" WARN
  if [ -f "$OSSEC" ] && ! grep -q 'docker-listener' "$OSSEC"; then
    sed -i 's|</ossec_config>|  <wodle name="docker-listener">\n    <disabled>no</disabled>\n  </wodle>\n\n</ossec_config>|' "$OSSEC"
  fi
  log "docker-listener enabled" OK
fi

# ---------- 5. MamorAI SSH access ----------
if [ "$DO_SSH" = yes ]; then
  log "--- MamorAI SSH access (user $SSH_USER) ---" STEP
  if ! id "$SSH_USER" >/dev/null 2>&1; then useradd -m -s /bin/bash -c "MamorAI (agent pack)" "$SSH_USER" >>"$LOG" 2>&1 || die "useradd $SSH_USER failed"; fi
  passwd -l "$SSH_USER" >/dev/null 2>&1 || true   # key only
  H="$(getent passwd "$SSH_USER" | cut -d: -f6)"; install -d -m 700 -o "$SSH_USER" -g "$(id -gn "$SSH_USER")" "$H/.ssh"
  AK="$H/.ssh/authorized_keys"; touch "$AK"
  OPTS="no-agent-forwarding,no-port-forwarding,no-X11-forwarding"
  [ -n "$SSH_FROM" ] && OPTS="from=\"$SSH_FROM\",$OPTS"
  KEYTYPE_B64="$(echo "$SSH_PUB" | awk '{print $1" "$2}')"
  grep -v 'mamorai-agent-pack' "$AK" > "$AK.tmp" 2>/dev/null || true
  echo "$OPTS $KEYTYPE_B64 mamorai-agent-pack" >> "$AK.tmp"
  mv "$AK.tmp" "$AK"; chown "$SSH_USER":"$(id -gn "$SSH_USER")" "$AK"; chmod 600 "$AK"
  SUDOF="/etc/sudoers.d/90-mamorai"
  if [ "$SSH_SUDO" = full ]; then
    echo "# MamorAI agent pack: host scans and host actions (stop a service, block a port / IP, isolate) run through sudo -n bash -c" > "$SUDOF.tmp"
    echo "$SSH_USER ALL=(root) NOPASSWD: ALL" >> "$SUDOF.tmp"
    chmod 440 "$SUDOF.tmp"
    visudo -cf "$SUDOF.tmp" >>"$LOG" 2>&1 || { rm -f "$SUDOF.tmp"; die "sudoers check failed"; }
    mv "$SUDOF.tmp" "$SUDOF"
  else rm -f "$SUDOF"; fi
  if grep -qiE '^\s*(AllowUsers|AllowGroups)\s' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null; then
    log "sshd has AllowUsers / AllowGroups: add '$SSH_USER' there yourself, or MamorAI cannot log in" WARN
  fi
  log "SSH access for MamorAI: user $SSH_USER, from ${SSH_FROM:-anywhere}, sudo $SSH_SUDO" OK
  for f in /etc/ssh/ssh_host_ed25519_key.pub /etc/ssh/ssh_host_ecdsa_key.pub; do [ -f "$f" ] && log "host key (compare with MamorAI on the first connection): $(ssh-keygen -lf "$f" 2>/dev/null)"; done
elif id "$SSH_USER" >/dev/null 2>&1 && grep -qs 'mamorai-agent-pack' "$(getent passwd "$SSH_USER" | cut -d: -f6)/.ssh/authorized_keys" && [ "$DO_SSH" = no ]; then
  log "MamorAI SSH access stays as it is (to remove it: userdel -r $SSH_USER; rm -f /etc/sudoers.d/90-mamorai)" WARN
fi

# ---------- 6. start + state ----------
log "--- start ---" STEP
install -d -m 755 "$STATE_DIR"
printf '{\n  "rev": %s,\n  "os": "linux",\n  "mode": "%s",\n  "wazuh": "%s",\n  "group": "%s",\n  "mamorai_ssh": %s,\n  "installed_at": "%s"\n}\n' \
  "$PACK_REV" "$MODE" "$WAZUH_VERSION" "$AGENT_GROUP" "$( [ "$DO_SSH" = yes ] && echo true || echo false )" "$(date -Iseconds)" > "$STATE"
chmod 644 "$STATE"
systemctl daemon-reload >>"$LOG" 2>&1 || true
systemctl enable wazuh-agent >>"$LOG" 2>&1 || true
START_TS="$(date '+%Y/%m/%d %H:%M:%S')"
systemctl restart wazuh-agent >>"$LOG" 2>&1 || die "wazuh-agent did not start"
OK=0
for _ in $(seq 1 24); do
  if awk -v t="$START_TS" 'substr($0,1,19) >= t' /var/ossec/logs/ossec.log 2>/dev/null | grep -q "Connected to the server"; then OK=1; break; fi
  sleep 5
done
echo
if [ "$OK" -eq 1 ]; then log "===== done: mode $MODE, pack r$PACK_REV — connected to the manager =====" OK; RC=0
else log "===== done, but no connection to the manager yet (tail -30 /var/ossec/logs/ossec.log) =====" WARN; RC=$([ "$MODE" = install ] && echo 1 || echo 0); fi
echo "  agent name : $AGENT_NAME     group : $AGENT_GROUP     manager : $MANAGERS"
echo "  agent      : $(systemctl is-active wazuh-agent 2>/dev/null)   auditd : $(systemctl is-active auditd 2>/dev/null)   MamorAI SSH : $DO_SSH"
echo "  log        : $LOG"
[ "$DO_SSH" = yes ] && echo "  in MamorAI : host screen -> this server -> 'Use the SSH prepared by the agent pack'"

# EDR-138: the extracted pack holds the Tailscale key / enrollment password: delete it (and its zip next to it) after success
if [ "$RC" -eq 0 ] && [ "$KEEP_FILES" -eq 0 ]; then
  NAME="$(basename "$HERE")"; PARENT="$(dirname "$HERE")"
  if [[ "$NAME" =~ ^MamorAI-Agent-Linux-r[0-9]+$ ]] && [ -f "$HERE/pack.json" ] && [ "$PARENT" != "/" ] && [ -n "$PARENT" ]; then
    cd / || true
    for z in "$PARENT/$NAME.zip" "$PARENT/$NAME-offline.zip"; do [ -f "$z" ] && rm -f "$z" && log "deleted the pack zip: $z" OK; done
    rm -rf -- "$HERE" && log "deleted the extracted pack: $HERE (use --keep-files to keep it)" OK
  else
    [ -n "$PY" ] && "$PY" - "$CFG" <<'PYEOF' 2>/dev/null && log "secrets removed from config.json (folder kept: unexpected name / location)" WARN
import json, sys
p = sys.argv[1]; c = json.load(open(p)); c["registrationPassword"] = ""; c["tailscaleAuthKey"] = ""; json.dump(c, open(p, "w"), indent=2)
PYEOF
  fi
fi
exit $RC
